// @vitest-environment jsdom
import {act,renderHook} from "@testing-library/react";import {expect,test,vi} from "vitest";import {useSelection} from "./useSelection";import {useToggle} from "./useToggle";import {useControllableState} from "./useControllableState";
test("toggle zachowuje poprzedni snapshot i nie gubi batcha",()=>{const {result}=renderHook(useSelection);const before=result.current.selectedIds;act(()=>{result.current.toggle(1);result.current.toggle(2);});expect([...result.current.selectedIds]).toEqual([1,2]);expect([...before]).toEqual([]);act(()=>result.current.toggle(1));expect([...result.current.selectedIds]).toEqual([2]);});
test("setAll usuwa tylko wskazane ID, deduplikuje i clear czyści",()=>{const {result}=renderHook(useSelection);act(()=>result.current.setAll([1,2,2,3],true));expect([...result.current.selectedIds]).toEqual([1,2,3]);act(()=>result.current.setAll([1,8],false));expect([...result.current.selectedIds]).toEqual([2,3]);act(()=>result.current.clear());expect(result.current.selectedIds.size).toBe(0);});
test("instancje hooka nie dzielą wyboru",()=>{const first=renderHook(useSelection),second=renderHook(useSelection);act(()=>first.result.current.toggle(42));expect(first.result.current.selectedIds.has(42)).toBe(true);expect(second.result.current.selectedIds.size).toBe(0);});
test("dwa toggle w jednym act zachowują false",()=>{const {result,rerender}=renderHook(({initial})=>useToggle(initial),{initialProps:{initial:false}});act(()=>{result.current.toggle();result.current.toggle();});expect(result.current.value).toBe(false);rerender({initial:true});expect(result.current.value).toBe(false);});
test("niekontrolowany setter funkcyjny obsługuje batch",()=>{const {result}=renderHook(()=>useControllableState({defaultValue:0}));act(()=>{result.current[1](value=>value+1);result.current[1](value=>value+1);});expect(result.current[0]).toBe(2);});
test("kontrolowany setter proponuje zmianę, props są źródłem prawdy",()=>{const onChange=vi.fn<(value:string[])=>void>();const {result,rerender}=renderHook(({value})=>useControllableState({value,defaultValue:[],onChange}),{initialProps:{value:["api"]}});act(()=>result.current[1](previous=>[...previous,"ui"]));expect(onChange).toHaveBeenCalledExactlyOnceWith(["api","ui"]);expect(result.current[0]).toEqual(["api"]);rerender({value:["api","ui"]});expect(result.current[0]).toEqual(["api","ui"]);});
test("nowe defaultValue nie resetuje stanu, nowy callback jest używany",()=>{const first=vi.fn(),second=vi.fn();const local=renderHook(({seed})=>useControllableState({defaultValue:seed}),{initialProps:{seed:1}});local.rerender({seed:99});expect(local.result.current[0]).toBe(1);const controlled=renderHook(({callback})=>useControllableState({value:4,defaultValue:0,onChange:callback}),{initialProps:{callback:first}});controlled.rerender({callback:second});act(()=>controlled.result.current[1](5));expect(first).not.toHaveBeenCalled();expect(second).toHaveBeenCalledExactlyOnceWith(5);});
test("zmiana trybu jest jawnie odrzucona",()=>{const hook=renderHook(({value}:{value:number|undefined})=>useControllableState({value,defaultValue:1}),{initialProps:{value:undefined} as {value:number|undefined}});expect(()=>hook.rerender({value:2})).toThrow(/Nie zmieniaj trybu/);});

