import {useCallback,useRef,useState,type SetStateAction} from "react";
type Options<T>={value?:T;defaultValue:T;onChange?:(value:T)=>void};
export function useControllableState<T>({value,defaultValue,onChange}:Options<T>):readonly [T,(next:SetStateAction<T>)=>void]{const controlled=useRef(value!==undefined).current;const [internal,setInternal]=useState<T>(()=>defaultValue);const current=controlled?value as T:internal;const set=useCallback((next:SetStateAction<T>)=>{if(controlled){const resolved=typeof next==="function"?(next as (previous:T)=>T)(current):next;onChange?.(resolved);}else setInternal(next);},[controlled,current,onChange]);if(controlled!==(value!==undefined))throw Error("Nie zmieniaj trybu kontrolowania podczas życia hooka");return [current,set];}

