import {createContext,useCallback,useContext,useState,type ReactNode} from "react";
export type Prefs={density:"compact"|"comfortable";dateFormat:"relative"|"absolute"};type Value={prefs:Prefs;updatePrefs:(patch:Partial<Prefs>)=>void};const Context=createContext<Value|null>(null);
export function PrefsProvider({children,initialPrefs}:{children:ReactNode;initialPrefs?:Partial<Prefs>}){const [prefs,setPrefs]=useState<Prefs>(()=>({density:"comfortable",dateFormat:"relative",...initialPrefs}));const updatePrefs=useCallback((patch:Partial<Prefs>)=>setPrefs(previous=>({...previous,...patch})),[]);return <Context.Provider value={{prefs,updatePrefs}}>{children}</Context.Provider>;}
export function usePrefs(){const value=useContext(Context);if(!value)throw Error("usePrefs działa wyłącznie wewnątrz <PrefsProvider>");return value;}

// @vitest-environment jsdom
import {act,render,renderHook,screen} from "@testing-library/react";import {MemoryRouter} from "react-router";import userEvent from "@testing-library/user-event";import type {ReactNode} from "react";import {expect,test,vi} from "vitest";import {PrefsProvider,usePrefs} from "./PrefsContext";import {useTicketFilters} from "./useTicketFilters";import {useCombobox,ComboboxProbe} from "./useCombobox";
test("provider łączy poprawki bez utraty innych pól",()=>{const wrapper=({children}:{children:ReactNode})=><PrefsProvider>{children}</PrefsProvider>;const {result}=renderHook(usePrefs,{wrapper});act(()=>{result.current.updatePrefs({density:"compact"});result.current.updatePrefs({dateFormat:"absolute"});});expect(result.current.prefs).toEqual({density:"compact",dateFormat:"absolute"});});
test("brak providera rzuca czytelny błąd",()=>{const spy=vi.spyOn(console,"error").mockImplementation(()=>{});try{expect(()=>renderHook(usePrefs)).toThrow(/wewnątrz <PrefsProvider>/);}finally{spy.mockRestore();}});
test("fabryka wrappera przekazuje seed, instancje pozostają niezależne",()=>{const makeWrapper=(density:"compact"|"comfortable")=>function Wrapper({children}:{children:ReactNode}){return <PrefsProvider initialPrefs={{density}}>{children}</PrefsProvider>;};const first=renderHook(usePrefs,{wrapper:makeWrapper("compact")}),second=renderHook(usePrefs,{wrapper:makeWrapper("comfortable")});act(()=>first.result.current.updatePrefs({dateFormat:"absolute"}));expect(second.result.current.prefs).toEqual({density:"comfortable",dateFormat:"relative"});});
test("zmiana tagu resetuje stronę, usunięcie tagu czyści parametr",()=>{const wrapper=({children}:{children:ReactNode})=><MemoryRouter initialEntries={["/tickets?page=4&tag=api&owner=ola"]}>{children}</MemoryRouter>;const {result}=renderHook(useTicketFilters,{wrapper});expect(result.current.page).toBe(4);act(()=>result.current.setTag(" ui "));expect(result.current).toMatchObject({page:1,tag:"ui"});act(()=>result.current.setTag("   "));expect(result.current.tag).toBe("");});
test("hook filtrów potrzebuje routera i normalizuje niepoprawną stronę",()=>{const wrapper=({children}:{children:ReactNode})=><MemoryRouter initialEntries={["/?page=-3"]}>{children}</MemoryRouter>;expect(renderHook(useTicketFilters,{wrapper}).result.current.page).toBe(1);});
test("combobox obsługuje brak wyników bez wyboru undefined",()=>{const {result}=renderHook(()=>useCombobox(["API","UI"]));act(()=>result.current.search("brak"));expect(result.current.activeIndex).toBe(-1);act(()=>{result.current.move(1);result.current.choose();});expect(result.current.selected).toBeNull();});
test("filtrowanie, strzałki i wybór działają przez komponent kontrolny",async()=>{const user=userEvent.setup();render(<ComboboxProbe/>);const input=screen.getByRole("combobox",{name:"Tag"});await user.type(input,"a");expect(screen.getAllByRole("option").map(el=>el.textContent)).toEqual(["API","Auth"]);await user.keyboard("{ArrowDown}{Enter}");expect(screen.getByRole("status")).toHaveTextContent("Wybrano: Auth");expect(input).toHaveAttribute("aria-activedescendant",screen.getByRole("option",{name:"Auth"}).id);});

