afterEach(()=>vi.useRealTimers());test("interwał zmienia wynik, nowy start nie tworzy dwóch timerów",()=>{vi.useFakeTimers();vi.setSystemTime(10000);const {result,rerender,unmount}=renderHook(({start})=>useSecondsSince(start),{initialProps:{start:10000}});act(()=>vi.advanceTimersByTime(3000));expect(result.current).toBe(3);rerender({start:12000});expect(result.current).toBe(1);expect(vi.getTimerCount()).toBe(1);unmount();expect(vi.getTimerCount()).toBe(0);});test("StrictMode nie zostawia interwałów po unmount",()=>{vi.useFakeTimers();vi.setSystemTime(5000);const wrapper=({children}:{children:ReactNode})=><StrictMode>{children}</StrictMode>;const {result,unmount}=renderHook(()=>useSecondsSince(5000),{wrapper});expect(vi.getTimerCount()).toBe(1);act(()=>vi.advanceTimersByTime(2000));expect(result.current).toBe(2);unmount();expect(vi.getTimerCount()).toBe(0);act(()=>vi.advanceTimersByTime(9000));expect(result.current).toBe(2);});

