import {createStore} from "zustand/vanilla";export type Item={ticketId:number;note:string};type State={items:Item[];add:(id:number)=>void;setNote:(id:number,note:string)=>void};export function createCart(){return createStore<State>()(set=>({items:[],add:id=>set(previous=>previous.items.some(item=>item.ticketId===id)||previous.items.length>=10?previous:{items:[...previous.items,{ticketId:id,note:""}]}),setNote:(id,note)=>set(previous=>({items:previous.items.map(item=>item.ticketId===id?{...item,note}:item)}))}));}
// Jawny kontrakt: wersja 0 to {ids:number[]}, wersja 1 to {items:Item[]}. Nie odczytuje storage.
export function migrateCart(raw:unknown,version:number):{items:Item[]}{if(!raw||typeof raw!=="object")return {items:[]};const object=raw as Record<string,unknown>;const candidates:unknown[]=version===0&&Array.isArray(object.ids)?object.ids.map(ticketId=>({ticketId,note:""})):version===1&&Array.isArray(object.items)?object.items:[];const items:Item[]=[];for(const candidate of candidates){if(!candidate||typeof candidate!=="object")continue;const item=candidate as Record<string,unknown>,id=item.ticketId;if(typeof id!=="number"||!Number.isSafeInteger(id)||id<1||items.some(row=>row.ticketId===id))continue;items.push({ticketId:id,note:typeof item.note==="string"?item.note:""});if(items.length===10)break;}return {items};}

