import {beforeEach,expect,test} from "vitest";import {createCart,migrateCart} from "./hookCart";
let store=createCart();beforeEach(()=>{store=createCart();});test("add nie dubluje ID, setNote zachowuje inne rekordy",()=>{store.getState().add(42);store.getState().add(42);store.getState().add(7);store.getState().setNote(42,"oddzwonić");expect(store.getState().items).toEqual([{ticketId:42,note:"oddzwonić"},{ticketId:7,note:""}]);});test("fabryka zapewnia pusty stan i limit 10 unikalnych pozycji",()=>{expect(store.getState().items).toEqual([]);for(let i=1;i<=12;i++)store.getState().add(i);expect(store.getState().items).toHaveLength(10);expect(createCart().getState().items).toEqual([]);});test("pełny reset musi zachować akcje",()=>{const initial=store.getInitialState();store.getState().add(42);store.setState(initial,true);expect(store.getState().items).toEqual([]);store.getState().add(7);expect(store.getState().items[0].ticketId).toBe(7);});test("subskrypcja odłącza się, brak zmiany nie emituje",()=>{let calls=0;const unsubscribe=store.subscribe(()=>{calls++;});store.getState().add(42);store.getState().add(42);expect(calls).toBe(1);unsubscribe();store.getState().add(7);expect(calls).toBe(1);});test("migracja v0 deduplikuje i odrzuca niepoprawne ID bez mutacji",()=>{const raw={ids:[42,42,-1,3.5,"7",7]};expect(migrateCart(raw,0)).toEqual({items:[{ticketId:42,note:""},{ticketId:7,note:""}]});expect(raw.ids).toEqual([42,42,-1,3.5,"7",7]);});test("migracja v1 kopiuje notatkę, nieznana wersja i uszkodzone dane są bezpieczne",()=>{const raw={items:[{ticketId:1,note:"opis"},{ticketId:2,note:44},null]};const migrated=migrateCart(raw,1);expect(migrated.items).toEqual([{ticketId:1,note:"opis"},{ticketId:2,note:""}]);migrated.items[0].note="nowa";expect(raw.items[0]?.note).toBe("opis");expect(migrateCart(null,0)).toEqual({items:[]});expect(migrateCart(raw,9)).toEqual({items:[]});});

